function App() {
  const [etat, setEtat] = useState("depart");
  let contenu = <p id="message">Choisis une démonstration.</p>;
  if (etat === "pret") { contenu = <p id="message">Catalogue fictif prêt.</p>; }

  if (etat === "erreur") { contenu = <section id="panne"><p id="message">Erreur de démonstration.</p><button id="reessayer" type="button" onClick={() => setEtat("pret")}>Revenir au catalogue</button></section>; }
  return <main><button id="pret" type="button" onClick={() => setEtat("pret")}>Voir un succès</button><button id="vide" type="button" onClick={() => setEtat("vide")}>Voir le vide</button><button id="erreur" type="button" onClick={() => setEtat("erreur")}>Voir une erreur</button><div id="resultat" aria-live="polite">{contenu}</div><p>États locaux de démonstration, sans requête.</p></main>;
}
root.render(<App />);

